import { readFile } from "node:fs/promises";

// Generated by scripts/vendor-grammars.ts on install.
const GRAMMARS_DIR = new URL("../../grammars/", import.meta.url);

/** The package's only file-system access: a grammar or query file vendored on install. */
export async function readGrammarFile(name: string): Promise<Uint8Array> {
  try {
    return new Uint8Array(await readFile(new URL(name, GRAMMARS_DIR)));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") throw new Error(`Grammar ${name} is missing: run pnpm install`);
    throw error;
  }
}
